/* The Launch Ledger — editorial ledger theme. Paper, ink, copper; no framework. */
:root{
  --paper:#faf6ef; --surface:#fffdf8; --paper2:#f3ede1;
  --ink:#1c1917; --muted:#78716c; --faint:#a8a29e;
  --rule:#e2d9c7; --rule2:#d6cbb4;
  --copper:#b45309; --copper-soft:#fef3c7;
  --green:#166534; --green-soft:#dcfce7;
  --red:#7f1d1d; --red-soft:#fee2e2;
  --serif:Georgia,'Times New Roman',serif;
  --sans:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  --mono:ui-monospace,'SF Mono',SFMono-Regular,Menlo,Consolas,monospace;
}
*{box-sizing:border-box}
html{background:var(--paper)}
body{margin:0 auto;max-width:1360px;padding:0 20px 64px;color:var(--ink);background:var(--paper);font-family:var(--sans);font-size:14px;line-height:1.42}
h1,h2,h3{font-family:var(--serif);font-weight:700;margin:0}
a{color:var(--copper)}
button{font:inherit;cursor:pointer}
select,input[type=text]{font:inherit;background:var(--surface);color:var(--ink);border:1px solid var(--rule2);border-radius:2px;padding:5px 8px}
input[type=range]{accent-color:var(--copper)}
.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}
/* masthead */
.masthead{padding:7px 0 6px;border-bottom:4px double var(--ink);margin-bottom:7px}
.mast-top{display:flex;justify-content:space-between;gap:12px;font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid var(--rule);padding-bottom:3px;margin-bottom:4px}
.masthead h1{font-size:20px;line-height:1.02;letter-spacing:-.01em;text-align:center}
.mast-sub{display:none}
/* proof + tape */
.proof{display:flex;flex-wrap:wrap;gap:4px 12px;align-items:center;border:1px solid var(--ink);background:var(--ink);color:#fff7e6;padding:5px 9px;margin-bottom:6px;font-size:11px}
.proof b{font-family:var(--mono);font-weight:700;color:#fbbf24}
.proof .ok{color:#86efac;font-weight:700}
.tape{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid var(--ink);border-top:3px solid var(--ink);background:var(--surface);margin-bottom:6px}
.tape>div{padding:5px 8px;border-left:1px solid var(--rule)}
.tape>div:first-child{border-left:0}
.tape .k{font-size:9px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}
.tape .v{font-family:var(--serif);font-size:15px;line-height:1.1;margin-top:0}
.tape .d{font-size:10px;color:var(--muted);line-height:1.25;margin-top:0}
.term-strip{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-bottom:6px}
.accounting{background:var(--surface);border:1px solid var(--rule);padding:3px 7px;margin-bottom:4px}
.accounting h3{font-size:12px;margin:0 0 3px}
.accounting .bar{height:14px;margin:2px 0}
.accounting .legend{font-size:8px;gap:1px 8px;flex-wrap:nowrap;overflow:hidden;white-space:nowrap}
.accounting .check-line{font-size:9px;margin-top:2px;padding-top:2px}
.formula-strip{display:grid;grid-template-columns:1.2fr .8fr;gap:6px;margin-bottom:6px}
.formula-strip .mini{background:var(--surface);border:1px solid var(--rule);padding:3px 6px}
.formula-strip svg{height:34px}
.formula-strip h3{font-size:12px;margin:0 0 2px}
.formula-strip p{font-size:9px;margin:1px 0;line-height:1.25}
.oddsbar{display:inline-block;width:34px;height:7px;background:var(--paper2);border:1px solid var(--rule2);vertical-align:middle;margin-left:5px}
.oddsbar i{display:block;height:100%;background:var(--copper)}
.rankrange{display:block;font-size:9px;color:var(--muted);font-family:var(--mono)}
.term-strip .mini{background:var(--surface);border:1px solid var(--rule);padding:3px 6px}
.term-strip h3{font-size:12px;margin:0 0 2px}
.term-strip table{font-size:8px}
.term-strip p{font-size:8px;margin:2px 0}
.term-strip .ev th,.term-strip .ev td{padding:0 3px;border-bottom:1px solid var(--rule);line-height:1.15}
.controls{display:grid;grid-template-columns:1fr 1.35fr;gap:6px;margin-bottom:6px}
.controls .panel{margin-bottom:0;padding:4px 6px}
.controls h2{font-size:13px;margin-bottom:2px}
.controls .note{display:none}
.lede{font-family:var(--serif);font-size:15px;line-height:1.42;margin:10px 0}
.lede b{color:var(--copper)}
/* panels and section heads */
.panel{background:var(--surface);border:1px solid var(--rule);padding:10px 12px;margin-bottom:10px}
.section-head{display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid var(--ink);padding-bottom:6px;margin-bottom:0}
.section-head h2{font-size:16px}
.section-head span{color:var(--muted);font-size:13px}
.panel h2{font-size:22px;margin-bottom:8px}
.panel h3{font-size:16px;margin:14px 0 6px}
.panel p{margin:6px 0}
.panel .note{color:var(--muted);font-size:13px}
/* scenario + filters */
.scenario-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px 10px;align-items:end}
.filter-grid{display:grid;grid-template-columns:repeat(5,minmax(104px,1fr));gap:4px 7px;align-items:end}
.filter-grid select,.filter-grid input[type=text]{width:100%;padding:2px 5px;font-size:12px}
.scenario-grid select{width:100%;padding:2px 5px;font-size:12px}
.field label{display:block;font-size:9px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);margin-bottom:2px}
.field .val{font-family:var(--mono);font-size:12px}
.check{font-size:12px;display:flex;gap:5px;align-items:center}
.scenario-out{margin-top:2px;padding-top:2px;border-top:1px solid var(--rule);font-size:11px}
/* tabs + table */
.tabs{display:flex;gap:0;margin:2px 0 0}
.tab{background:none;border:1px solid var(--rule2);border-bottom:0;padding:2px 10px;font-family:var(--serif);font-size:13px;color:var(--muted)}
.tab.on{background:var(--surface);color:var(--ink);border-color:var(--ink);border-bottom:1px solid var(--surface);margin-bottom:-1px;font-weight:700}
.table-scroll{overflow-x:auto;border:1px solid var(--ink);background:var(--surface)}
table{border-collapse:collapse;width:100%;font-size:13px}
th,td{padding:0 5px;text-align:left;border-bottom:1px solid var(--rule);vertical-align:top}
thead th{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid var(--ink);background:var(--paper2);position:sticky;top:0;white-space:nowrap}
thead th.sortable{cursor:pointer}
thead th.sortable:hover{color:var(--ink)}
tbody tr{cursor:pointer}
tbody tr:hover{background:var(--paper2)}
td.num,th.num{text-align:right;font-family:var(--mono);font-variant-numeric:tabular-nums;white-space:nowrap}
td.name{font-family:var(--serif);font-weight:700;font-size:12px;line-height:1.1}
td .sub{color:var(--muted);font-size:10px;font-family:var(--sans);font-weight:400;display:block;line-height:1.15;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:230px}
td .farmline{color:var(--ink);font-size:10px;font-family:var(--mono);display:block;line-height:1.15;white-space:nowrap}
.band{position:relative;height:5px;background:var(--paper2);border:1px solid var(--rule2);margin:2px 0 0;min-width:70px}
.band i{position:absolute;top:0;bottom:0;background:var(--copper);opacity:.75}
.band b{position:absolute;top:-2px;width:2px;height:9px;background:var(--ink)}
.range{font-size:11px;color:var(--muted);white-space:nowrap}
.tag{display:inline-block;font-size:10px;letter-spacing:.07em;text-transform:uppercase;border:1px solid var(--rule2);padding:1px 5px;margin-left:6px;color:var(--muted);vertical-align:1px}
.tag.w{border-color:var(--copper);color:var(--copper)}
.tag.p{border-color:var(--red);color:var(--red)}
.pos{color:var(--green)} .neg{color:var(--red)}
/* verdict chips */
.chip{display:inline-block;font-size:10px;letter-spacing:.08em;text-transform:uppercase;padding:0 5px;border:1px solid;border-radius:2px;white-space:nowrap}
.chip.farm{color:var(--green);border-color:var(--green);background:var(--green-soft)}
.chip.marginal{color:var(--copper);border-color:var(--copper);background:var(--copper-soft)}
.chip.skip{color:var(--red);border-color:var(--red);background:var(--red-soft)}
.empty{padding:18px;text-align:center;color:var(--muted)}
/* ledger bar */
.bar{display:flex;height:26px;border:1px solid var(--ink);margin:8px 0 6px;overflow:hidden}
.bar i{display:block;height:100%}
.legend{display:flex;flex-wrap:wrap;gap:4px 16px;font-size:13px;margin:4px 0}
.legend b{font-family:var(--mono);font-weight:400}
.check-line{font-size:13px;margin-top:8px;padding-top:8px;border-top:1px solid var(--rule)}
.check-line .ok{color:var(--green);font-weight:700}
/* evidence tables */
.ev{width:100%;border-collapse:collapse;font-size:13px;margin:6px 0}
.ev th,.ev td{padding:5px 8px;border-bottom:1px solid var(--rule)}
.ev th{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);text-align:right}
.ev th:first-child,.ev td:first-child{text-align:left}
.ev td{font-family:var(--mono);font-variant-numeric:tabular-nums;text-align:right}
.ev td.kept{color:var(--green)} .ev td.notkept{color:var(--faint)}
/* detail dialog */
dialog{border:1px solid var(--ink);background:var(--surface);color:var(--ink);max-width:720px;width:calc(100vw - 40px);padding:0}
dialog::backdrop{background:rgba(28,25,23,.45)}
.detail-head{padding:16px 20px 12px;border-bottom:3px double var(--ink);display:flex;justify-content:space-between;gap:12px}
.detail-head h3{font-size:28px;line-height:1.1}
.detail-head .sub{color:var(--muted);font-size:13px;margin-top:4px}
.detail-body{padding:14px 20px 20px}
.detail-body h4{font-family:var(--serif);font-size:17px;margin:16px 0 6px;border-bottom:1px solid var(--rule);padding-bottom:4px}
.kv{width:100%;border-collapse:collapse;font-size:14px}
.kv td{padding:5px 0;border-bottom:1px solid var(--rule)}
.kv td:first-child{color:var(--muted);width:46%}
.kv td:last-child{text-align:right;font-family:var(--mono);font-variant-numeric:tabular-nums}
.steps{margin:6px 0;padding-left:22px}
.steps li{margin:7px 0}
.steps .cost{color:var(--muted);font-size:13px}
.verdict-box{border:1px solid var(--ink);padding:12px 14px;margin-top:6px;background:var(--paper)}
.verdict-box .big{font-family:var(--serif);font-size:22px}
.close-x{background:none;border:1px solid var(--rule2);padding:4px 10px;font-size:14px}
@media (max-width:900px){.tape{grid-template-columns:repeat(3,1fr)}.tape>div{border-top:1px solid var(--rule)}.term-strip{grid-template-columns:1fr}.masthead h1{font-size:34px}}
@media (max-width:560px){.tape{grid-template-columns:repeat(2,1fr)}body{padding:0 12px 48px}}
```

